// File: src/lib/llm/narrate.ts
// Narration grounded ONLY in Qloo's REAL rank/affinity/explainability data, GENERATED by the 0G
// Compute Router (the SOLE narration brain). USER DIRECTIVE 2026-10-29 (no-fallback): the
// deterministic template render is REMOVED as an operating path — narration is either real 0G prose
// grounded in the given Qloo facts, or an HONEST failure (null). We NEVER emit a fabricated template
// passed off as the agent's provenance voice. narrate() is ASYNC and lives OFF the /api/gift
// critical path (the lazy /api/narrate route), so E-2 (≤6s cold path) is unaffected and a narration
// failure never blanks the gift grid (narration is additive). Constrained by prompt to add NO numbers
// or claims beyond the given Qloo facts (NN-3).
import type { Provenance } from "@/lib/types";
import { llmConfigured, chatText } from "@/lib/llm/client";

// Thrown when the sole 0G narration path is unavailable/failed. The /api/narrate route maps this to
// an honest { narration: null, available: false } — the UI shows "narration unavailable", never a
// fabricated template.
export class NarrationUnavailableError extends Error {
  constructor(cause: string) {
    super(`NARRATION_UNAVAILABLE: ${cause}`);
    this.name = "NarrationUnavailableError";
  }
}

const SYS =
  "You write ONE warm, concise sentence recommending a gift. Use ONLY the facts given. Do NOT add " +
  "any numbers, percentages, or claims not in the facts. Do not mention ranking positions as percentages.";

export async function narrate(prov: Provenance): Promise<string> {
  // No-fallback: with no key configured there is NO narration path. Fail honestly.
  if (!llmConfigured()) throw new NarrationUnavailableError("0G key not configured");
  // Ground the LLM in the REAL Qloo fields only: the rank statement (query rank), the affinity band
  // (query.affinity), and the top contributors (query.explainability signal drivers). No numbers are
  // added by the model (NN-3) — they are already present, honest, and Qloo-derived in these facts.
  const facts = JSON.stringify({
    rankStatement: prov.qlooSays.rankStatement,
    affinityBand: prov.qlooSays.affinityBand,
    topContributors: prov.qlooSays.topContributors,
    reason: prov.weChose.reason,
  });
  let text: string;
  try {
    text = (await chatText(SYS, `Facts:\n${facts}`)).trim();
  } catch (e) {
    throw new NarrationUnavailableError(String((e as Error).message));
  }
  // An empty completion is a failed generation, not a valid narration — fail honestly rather than
  // return "" that the UI would render as blank-but-present.
  if (!text) throw new NarrationUnavailableError("empty 0G completion");
  return text;
}
